    { t: "③ 개념 정리", c: 2, w: "wl", b: [fill("f", [["평면거울에 생기는 상의 크기는 물체의 크기와", ["같다", "작다"], 0, "."], ["상에서 거울까지의 거리는 물체에서 거울까지의 거리와", ["같다", "다르다"], 0, "."], ["평면거울에 비친 상은", ["좌우가 바뀌어", "위아래가 바뀌어"], 0, "보인다."], ["평면거울에서 상이 생기는 것은 빛의", ["반사", "굴절"], 0, " 때문이다."]]), con("물체에서 나온 빛이 거울에서 반사 법칙에 따라 반사되어 눈에 들어와요.<br><br>우리 눈은 빛이 곧게 나아간다고 생각해서, 반사된 빛의 <b>연장선</b>이 모이는 거울 뒤쪽에 물체가 있는 것처럼 느껴요. 이것이 <b>상</b>이에요.")] },
    { t: "④ 적용 활동", c: 2, w: "wl", b: [calc("c1", "거울에서 <b>1.5 m</b> 떨어진 곳에 서 있다. 나와 거울 속 내 모습(상) 사이의 거리는?", 3, "m", "상은 거울 뒤 1.5 m에 생기므로 1.5 + 1.5 = 3 m예요.", "상은 거울 뒤 어디에 생길까요?", .01), short("think", "사고력: 구급차 앞에 글자를 좌우가 바뀌게 쓰는 까닭을 써 보자.", "앞차의 운전자가…", "앞차 운전자가 뒷거울(평면거울)로 볼 때 좌우가 다시 바뀌어 바른 글자로 읽히게 하기 위해서이다.")] },
    { t: "⑤ 확인 문제", b: [quiz([Q("거울 앞 2 m에 서 있다가 거울 쪽으로 1 m 다가가면 상까지의 거리는?", ["2 m", "4 m", "1 m", "3 m"], 0, "거울까지 1 m, 상까지 1 m → 2 m"), Q("평면거울 상의 특징이 아닌 것은?", ["물체보다 작다", "좌우가 바뀐다", "크기가 같다", "거리가 같다"], 0, "크기는 물체와 같아요."), Q("평면거울에 생긴 상에 대한 설명으로 옳은 것은?", ["반사된 빛의 연장선이 모이는 곳에 생긴다", "거울 표면에 생긴다", "거울 앞에 생긴다", "빛이 굴절해서 생긴다"], 0, "그래서 거울 뒤에 있는 것처럼 보여요."), Q("호수에 산이 거꾸로 비치는 것과 같은 원리는?", ["평면거울의 반사", "렌즈의 굴절", "빛의 합성", "그림자"], 0, "잔잔한 수면이 평면거울 역할을 해요.")])] },
    END("평면거울에서 상이 생기는 원리를 설명해 보자.", "물체에서 나온 빛이…", "물체에서 나온 빛이 평면거울에서 반사 법칙에 따라 반사되어 눈에 들어오고, 눈은 반사된 빛의 연장선이 모이는 거울 뒤쪽에 물체가 있는 것처럼 느낀다. 상은 물체와 크기, 거리가 같고 좌우가 바뀐다.")
